-- Creovision: catálogo Tarot completo (78 cartas).
-- Preparado para revisión y aplicación manual. No se ejecuta desde el frontend.
-- Requiere que la tabla public.tarot_cards ya exista.

ON CONFLICT (slug) DO UPDATE SET
  card_key = EXCLUDED.card_key,
  name = EXCLUDED.name,
  arcana = EXCLUDED.arcana,
  number = EXCLUDED.number,
  suit = EXCLUDED.suit,
  rank = EXCLUDED.rank,
  summary = EXCLUDED.summary,
  upright_meaning = EXCLUDED.upright_meaning,
  reversed_meaning = EXCLUDED.reversed_meaning,
  keywords = EXCLUDED.keywords,
  reflection_question = EXCLUDED.reflection_question,
  yes_no_tendency = EXCLUDED.yes_no_tendency,
  image_key = EXCLUDED.image_key,
  display_order = EXCLUDED.display_order,
  status = EXCLUDED.status,
  is_demo = EXCLUDED.is_demo,
  seo_title = EXCLUDED.seo_title,
  seo_description = EXCLUDED.seo_description,
  published_at = EXCLUDED.published_at;

-- Si la tabla contiene demos adicionales, revisarlos antes de archivarlos.
-- Esta sentencia no borra cartas ni datos existentes.
