INSERT INTO public.tarot_cards (card_key, slug, name, arcana, number, suit, rank, summary, upright_meaning, reversed_meaning, keywords, reflection_question, yes_no_tendency, image_key, display_order, status, is_demo, seo_title, seo_description, published_at)
VALUES
  ('el_loco', 'el-loco', 'El Loco', 'major', 0, NULL, NULL, 'Un llamado a iniciar desde la libertad y la curiosidad, confiando en el presente.', 'Representa impulso hacia lo desconocido, confianza en el propio instinto y apertura a nuevas experiencias; su energía invita a comenzar sin plan rígido, aceptar riesgo creativo y descubrir aprendizajes inesperados mientras se mantiene atención en el presente y en la capacidad de adaptarse.', 'Lectura alternativa o bloqueo: señala vacilación, temores que frenan el salto y dispersión de energía; sugiere revisar impulsos no examinados y evitar decisiones precipitadas, crear estructura mínima para sostener ideas y recuperar confianza antes de emprender cambios significativos.', '["inicio","libertad","impulso","aventura"]'::jsonb, '¿Qué pequeño paso libre de perfección puedes dar hoy para explorar lo desconocido?', 'open', 'tarot_card_el_loco', 0, 'published', false, 'El Loco — significado del Tarot | Creovision', 'Un llamado a iniciar desde la libertad y la curiosidad, confiando en el presente.', TIMESTAMPTZ '2026-08-27 00:00:00+00'),
  ('el_mago', 'el-mago', 'El Mago', 'major', 1, NULL, NULL, 'Recuerda que tienes recursos y habilidad para transformar intención en acción con enfoque.', 'Actúa como puente entre intención y manifestación, recordando que dispones de recursos internos y habilidades para transformar ideas en resultados; invita a concentrar voluntad, comunicar con claridad y alinear herramientas disponibles para avanzar con creatividad y propósito.', 'Bloqueo: habilidades dispersas o dudas sobre competencia que impiden materializar proyectos; sugiere reevaluar metodología, practicar tareas concretas, pedir apoyo para complementar recursos y recuperar foco antes de intentar iniciativas donde la dirección y la técnica importan.', '["voluntad","habilidad","creación","concentración"]'::jsonb, '¿Qué habilidad concreta puedes usar hoy para avanzar en tu intención?', 'favorable', 'tarot_card_el_mago', 10, 'published', false, 'El Mago — significado del Tarot | Creovision', 'Recuerda que tienes recursos y habilidad para transformar intención en acción con enfoque.', TIMESTAMPTZ '2026-08-27 00:00:00+00'),
  ('la_sacerdotisa', 'la-sacerdotisa', 'La Sacerdotisa', 'major', 2, NULL, NULL, 'Un espacio para escuchar la voz interior y permitir que la intuición guíe en silencio.', 'Simboliza intuición, conocimiento interior y la paciencia para escuchar revelaciones internas; invita a respetar el silencio, explorar símbolos personales y confiar en procesos subconscientes antes de actuar, dejando que la comprensión emerja sin forzar resultados inmediatos.', 'Lectura alterna: bloqueo en el acceso interior, confusión entre intuición y miedo; sugiere crear rituales observables, registrar sueños o sensaciones, pedir tiempo para procesar información y evitar decisiones importantes hasta clarificar señales internas y consultar fuentes creativas.', '["intuición","silencio","misterio","sabiduría"]'::jsonb, '¿Qué señal interior estás ignorando que merece atención?', 'caution', 'tarot_card_la_sacerdotisa', 20, 'published', false, 'La Sacerdotisa — significado del Tarot | Creovision', 'Un espacio para escuchar la voz interior y permitir que la intuición guíe en silencio.', TIMESTAMPTZ '2026-08-27 00:00:00+00'),
  ('la_emperatriz', 'la-emperatriz', 'La Emperatriz', 'major', 3, NULL, NULL, 'Fomenta cultivar y proteger lo que da vida, creatividad y bienestar en lo cotidiano.', 'Encara fertilidad, abundancia creativa y cuidado tangible; invita a nutrir proyectos y relaciones con atención, cultivar ambientes fértiles y disfrutar del placer sensorial como fuente de inspiración y crecimiento sostenido; promueve la paciencia y establecer límites sanos para sostener ese flujo de recursos.', 'Bloqueo: exceso de complacencia o dependencia en la comodidad que estanca la creatividad; sugiere revisar hábitos de cuidado, compartir responsabilidades, recuperar iniciativa y proteger tus fuentes de apoyo para reactivar productividad y bienestar en la vida diaria.', '["abundancia","cuidado","creatividad","nutrición"]'::jsonb, '¿Qué espacio puedes preparar hoy para que una idea crezca con calma?', 'favorable', 'tarot_card_la_emperatriz', 30, 'published', false, 'La Emperatriz — significado del Tarot | Creovision', 'Fomenta cultivar y proteger lo que da vida, creatividad y bienestar en lo cotidiano.', TIMESTAMPTZ '2026-08-27 00:00:00+00'),
  ('el_emperador', 'el-emperador', 'El Emperador', 'major', 4, NULL, NULL, 'Inspira organizarse con autoridad responsable para construir bases firmes y predecibles.', 'Arquetipo de orden, estructura y autoridad responsable; invita a tomar decisiones firmes, establecer límites claros y organizar recursos con disciplina para construir bases estables y sostener proyectos a largo plazo, manteniendo integridad y previsión ante retos.', 'Bloqueo: rigidez excesiva o miedo a perder control que limita flexibilidad; sugiere suavizar normas, delegar con confianza, revisar supuestos autoritarios y adaptar estrategias para equilibrar seguridad con creatividad práctica, fomentar ambientes más colaborativos y sostenibles.', '["orden","autoridad","estabilidad","disciplina"]'::jsonb, '¿Qué regla puedes ajustar para mantener firmeza sin sofocar nuevas ideas?', 'caution', 'tarot_card_el_emperador', 40, 'published', false, 'El Emperador — significado del Tarot | Creovision', 'Inspira organizarse con autoridad responsable para construir bases firmes y predecibles.', TIMESTAMPTZ '2026-08-27 00:00:00+00'),
  ('el_sumo_sacerdote', 'el-sumo-sacerdote', 'El Sumo Sacerdote', 'major', 5, NULL, NULL, 'Invita a aprender en comunidad, buscar guía y armonizar creencias con prácticas comunes.', 'Representa tradición, aprendizaje guiado y valores compartidos; invita a buscar mentoría, participar en comunidades que ofrecen estructura moral y aprender a integrar creencias personales con prácticas que dan sentido colectivo y discernir qué aspectos adaptar al presente.', 'Bloqueo: adhesión automática a normas que ya no sirven o dificultad para cuestionar tradiciones; sugiere evaluar creencias, probar alternativas respetuosas y elegir prácticas que reflejen autenticidad personal y conexión real con otros en tu entorno cercano.', '["tradición","enseñanza","comunidad","valores"]'::jsonb, '¿Qué enseñanza heredada ya no resuena contigo y merece revisión?', 'open', 'tarot_card_el_sumo_sacerdote', 50, 'published', false, 'El Sumo Sacerdote — significado del Tarot | Creovision', 'Invita a aprender en comunidad, buscar guía y armonizar creencias con prácticas comunes.', TIMESTAMPTZ '2026-08-27 00:00:00+00'),
  ('los_enamorados', 'los-enamorados', 'Los Enamorados', 'major', 6, NULL, NULL, 'Trata sobre decidir desde el corazón, buscando coherencia entre deseo y responsabilidad compartida.', 'Habla de elecciones significativas en el corazón, armonía entre deseos y valores, y la posibilidad de aliarse con otros desde autenticidad; invita a decidir desde claridad emocional y responsabilidad compartida, considerando consecuencias y crecimiento mutuo.', 'Lectura alternativa: conflicto interno, indecisión entre caminos o proyección de expectativas en relaciones; sugiere clarificar prioridades personales, dialogar abiertamente y evitar elegir sólo para complacer o evitar soledad, a fin de tomar una decisión que honre a ambas partes.', '["elección","amor","alineación","compromiso"]'::jsonb, '¿Qué criterio personal debes priorizar al tomar esta decisión afectiva?', 'caution', 'tarot_card_los_enamorados', 60, 'published', false, 'Los Enamorados — significado del Tarot | Creovision', 'Trata sobre decidir desde el corazón, buscando coherencia entre deseo y responsabilidad compartida.', TIMESTAMPTZ '2026-08-27 00:00:00+00'),
  ('el_carro', 'el-carro', 'El Carro', 'major', 7, NULL, NULL, 'Señala la necesidad de dirigir fuerzas opuestas hacia un objetivo común con disciplina.', 'Indica impulso dirigido, disciplina en la acción y control sobre fuerzas opuestas; propone fijar metas claras, coordinar recursos y mantener determinación para avanzar con velocidad y coherencia, asumiendo responsabilidad por las decisiones tomadas y celebrando cada logro parcial.', 'Bloqueo: empuje desordenado o exceso de prisa que crea choques; sugiere pausar para reevaluar dirección, realinear intención con recursos reales y coordinar equipo antes de acelerar nuevamente para asegurar progreso sostenido sin sacrificar seguridad ni cohesión.', '["voluntad","dirección","control","avance"]'::jsonb, '¿Qué objetivo concreto te ayuda a orientar tu esfuerzo en las próximas dos semanas?', 'favorable', 'tarot_card_el_carro', 70, 'published', false, 'El Carro — significado del Tarot | Creovision', 'Señala la necesidad de dirigir fuerzas opuestas hacia un objetivo común con disciplina.', TIMESTAMPTZ '2026-08-27 00:00:00+00'),
  ('la_justicia', 'la-justicia', 'La Justicia', 'major', 8, NULL, NULL, 'Invita a evaluar con honestidad y buscar soluciones equilibradas basadas en hechos y principios.', 'Representa equilibrio, verdad y consecuencias justas; invita a evaluar decisiones con honestidad, asumir responsabilidad por actos pasados y buscar soluciones equilibradas basadas en hechos y principios éticos que reparen daños y restablezcan confianza donde sea posible.', 'Bloqueo: parcialidad, evitación de responsabilidad o falta de información que impide resolución justa; sugiere recopilar datos, escuchar partes implicadas, y establecer criterios claros antes de emitir juicios o firmar acuerdos para sostener decisiones equitativas en el tiempo.', '["equilibrio","verdad","responsabilidad","ley"]'::jsonb, '¿Qué información adicional necesitas para tomar una decisión justa?', 'caution', 'tarot_card_la_justicia', 80, 'published', false, 'La Justicia — significado del Tarot | Creovision', 'Invita a evaluar con honestidad y buscar soluciones equilibradas basadas en hechos y principios.', TIMESTAMPTZ '2026-08-27 00:00:00+00'),
  ('el_ermitano', 'el-ermitano', 'El Ermitaño', 'major', 9, NULL, NULL, 'Propone el retiro consciente para encontrar claridad, sabiduría y decisiones más conscientes.', 'Habla de retiro reflexivo, búsqueda de sabiduría propia y claridad interna; invita a tomar distancia del ruido cotidiano, iluminar dudas con tiempo y experimentar aprendizaje lento y consciente para que las próximas decisiones nazcan de una visión más profunda.', 'Bloqueo: aislamiento que conduce a estancamiento o a una visión demasiado interiorizada; sugiere buscar diálogo puntual con una persona de confianza, compartir hallazgos y contrastar perspectivas antes de tomar pasos importantes para evitar sesgos y reactivar claridad.', '["soledad","sabiduría","reflexión","claridad"]'::jsonb, '¿Qué pregunta poderosa puedes hacerte durante tu próximo periodo de silencio?', 'open', 'tarot_card_el_ermitano', 90, 'published', false, 'El Ermitaño — significado del Tarot | Creovision', 'Propone el retiro consciente para encontrar claridad, sabiduría y decisiones más conscientes.', TIMESTAMPTZ '2026-08-27 00:00:00+00'),
  ('la_rueda_de_la_fortuna', 'la-rueda-de-la-fortuna', 'La Rueda de la Fortuna', 'major', 10, NULL, NULL, 'Recuerda la naturaleza cíclica de los eventos y la necesidad de adaptarse con flexibilidad.', 'Simboliza ciclos, cambios inevitables y momentos de giro; invita a reconocer ritmos fluctuantes, adaptarse a nuevas circunstancias y aprovechar oportunidades que se alinean con un nuevo ciclo de vida, manteniendo perspectiva y actitudes flexibles frente a lo imprevisible.', 'Bloqueo: sensación de repetición o esperanza en cambios que no llegan por acción propia; sugiere identificar patrones, tomar responsabilidad por elecciones recurrentes y diseñar pequeños ajustes que alteren la dirección del ciclo para recuperar agencia.', '["cambio","ciclos","destino","adaptación"]'::jsonb, '¿Qué patrón repetido puedes modificar hoy para cambiar tu ciclo?', 'open', 'tarot_card_la_rueda_de_la_fortuna', 100, 'published', false, 'La Rueda de la Fortuna — significado del Tarot | Creovision', 'Recuerda la naturaleza cíclica de los eventos y la necesidad de adaptarse con flexibilidad.', TIMESTAMPTZ '2026-08-27 00:00:00+00'),
  ('la_fuerza', 'la-fuerza', 'La Fuerza', 'major', 11, NULL, NULL, 'Invita a ejercer coraje sereno y compasión al actuar, transformando tensión en resiliencia.', 'Expresa coraje sereno, dominio de impulsos y compasión aplicada; invita a enfrentar retos con calma, transformar tensión en resiliencia y liderar desde la templanza más que desde la fuerza bruta, cultivando paciencia y suavidad en la acción cotidiana.', 'Bloqueo: dudas sobre la propia fortaleza o esfuerzo excesivo que desgasta; sugiere practicar autocuidado, pedir apoyo cuando sea necesario y redescubrir fuentes internas de calma antes de forzar resultados para sostener resistencia a largo plazo.', '["valentía","templanza","compasión","resiliencia"]'::jsonb, '¿Cómo puedes mostrarte compasión mientras avanzas en este desafío?', 'favorable', 'tarot_card_la_fuerza', 110, 'published', false, 'La Fuerza — significado del Tarot | Creovision', 'Invita a ejercer coraje sereno y compasión al actuar, transformando tensión en resiliencia.', TIMESTAMPTZ '2026-08-27 00:00:00+00'),
  ('el_colgado', 'el-colgado', 'El Colgado', 'major', 12, NULL, NULL, 'Propone detenerse para cambiar el ángulo de visión y ganar nuevas comprensiones antes de seguir.', 'Invita a pausa reflexiva, cambio de perspectiva y sacrificio voluntario para acceder a nuevas comprensiones; propone soltar urgencias y observar desde otro ángulo antes de continuar, valorando qué merece espera y qué requiere acción inmediata.', 'Bloqueo: estancamiento disfrazado de contemplación o resistencia a soltar roles; sugiere distinguir entre pausa necesaria y evasión, probar pequeños intercambios de costumbre y permitir movimiento gradual para recuperar fluidez y revalorar prioridades con honestidad constante.', '["perspectiva","sacrificio","pausa","rendición"]'::jsonb, '¿Qué puedes dejar en pausa hoy para ver esta situación desde otro lugar?', 'caution', 'tarot_card_el_colgado', 120, 'published', false, 'El Colgado — significado del Tarot | Creovision', 'Propone detenerse para cambiar el ángulo de visión y ganar nuevas comprensiones antes de seguir.', TIMESTAMPTZ '2026-08-27 00:00:00+00'),
  ('la_muerte', 'la-muerte', 'La Muerte', 'major', 13, NULL, NULL, 'Cambio profundo que habilita un nuevo ciclo.', 'Fin necesario de una etapa que libera espacio para renovaciones internas y externas; permite soltar lo que ya no sirve y comenzar procesos distintos con mayor autenticidad. Es el pasaje hacia una transformación que depura y redefine identidad y propósito.', 'Resistencia al cambio que mantiene situaciones obsoletas; bloqueos emocionales, miedo a perder seguridad o negación de pasos necesarios. Indica estancamiento temporal que pide aceptación gradual y estrategias prácticas para integrar transiciones en lugar de rechazarlas, recuperando la capacidad de soltar con tiempo.', '["transformación","ciclos","soltar"]'::jsonb, '¿Qué necesitas dejar ir para permitir un nuevo comienzo?', 'open', 'tarot_card_la_muerte', 130, 'published', false, 'La Muerte — significado del Tarot | Creovision', 'Cambio profundo que habilita un nuevo ciclo.', TIMESTAMPTZ '2026-08-27 00:00:00+00'),
  ('la_templanza', 'la-templanza', 'La Templanza', 'major', 14, NULL, NULL, 'Equilibrio y mezcla armoniosa entre opuestos.', 'Búsqueda consciente de equilibrio entre fuerzas internas y externas; promueve paciencia, moderación y adaptabilidad. Favorece la sanación mediante ajustes pequeños y la combinación creativa de recursos distintos. Invita a integrar partes opuestas para alcanzar estabilidad y fluidez en el día a día.', 'Desajuste temporal que imita equilibrio pero oculta extremos; puede señalar prisa, falta de límites o dificultad para conciliar necesidades opuestas. Es una llamada a revisar hábitos, negociar prioridades y restablecer ritmos más pausados para recuperar armonía práctica sin esfuerzos bruscos.', '["moderación","armonía","paciencia","integración"]'::jsonb, '¿Dónde puedes aplicar más moderación para recuperar equilibrio?', 'favorable', 'tarot_card_la_templanza', 140, 'published', false, 'La Templanza — significado del Tarot | Creovision', 'Equilibrio y mezcla armoniosa entre opuestos.', TIMESTAMPTZ '2026-08-27 00:00:00+00'),
  ('el_diablo', 'el-diablo', 'El Diablo', 'major', 15, NULL, NULL, 'Ataduras materiales o patrones intensos que piden conciencia.', 'Enfoque en deseos, hábitos o acuerdos que generan intensidad y dependencia; revela la presencia de ataduras no examinadas que alimentan repetición y comodidad peligrosa. Ofrece la oportunidad de iluminar cadenas simbólicas y recuperar libertad a través de reconocimiento y cambio consciente.', 'Procesos internos que comienzan a desprenderse de patrones; aunque la liberación es incompleta, surgen fisuras en la dependencia. Suele marcar vacilación o miedo a soltar, y pide pasos pequeños que demuestren que la autonomía se puede reconstruir desde decisiones concretas.', '["ataduras","tentación","autonomía","compulsión"]'::jsonb, '¿Qué hábito o acuerdo podrías examinar para recuperar libertad?', 'caution', 'tarot_card_el_diablo', 150, 'published', false, 'El Diablo — significado del Tarot | Creovision', 'Ataduras materiales o patrones intensos que piden conciencia.', TIMESTAMPTZ '2026-08-27 00:00:00+00'),
  ('la_torre', 'la-torre', 'La Torre', 'major', 16, NULL, NULL, 'Colapso repentino que revela estructuras frágiles.', 'Ruptura súbita de estructuras frágiles que expone verdades ocultas y despeja ilusiones; provoca choque pero facilita reordenamiento más auténtico. Invita a aceptar la realidad sin maquillaje y emprender la reconstrucción con bases visibles y lecciones aprendidas.', 'Resistencia a aceptar la quiebra que evita cambios necesarios; puede indicar demora en reconstruir o intento de sostener lo insostenible. También sugiere la posibilidad de encontrar recursos internos para recomponer lentamente lo perdido y reconstruir con mayor claridad.', '["ruptura","revelación","reconstrucción","urgencia"]'::jsonb, '¿Qué verdad oculta podría transformar tu situación si la afrontas?', 'caution', 'tarot_card_la_torre', 160, 'published', false, 'La Torre — significado del Tarot | Creovision', 'Colapso repentino que revela estructuras frágiles.', TIMESTAMPTZ '2026-08-27 00:00:00+00'),
  ('la_estrella', 'la-estrella', 'La Estrella', 'major', 17, NULL, NULL, 'Esperanza y guía que renuevan confianza.', 'Renovación emocional y orientación suave que recupera confianza y sentido. Representa generosidad interior, creatividad y apertura hacia posibilidades más amplias; fomenta la reparación después de crisis y una visión calmada que guía pasos con optimismo práctico y coherencia.', 'Ilusión desgastada o esperanza frágil que necesita reafirmarse; puede indicar dudas creativas o falta de recursos emocionales para sostener el entusiasmo. Es una invitación a reconectar con prácticas restauradoras y a buscar apoyo para que la confianza vuelva a crecer paso a paso.', '["esperanza","sanación","inspiración","confianza"]'::jsonb, '¿Qué acto pequeño puede restaurar tu confianza hoy?', 'favorable', 'tarot_card_la_estrella', 170, 'published', false, 'La Estrella — significado del Tarot | Creovision', 'Esperanza y guía que renuevan confianza.', TIMESTAMPTZ '2026-08-27 00:00:00+00'),
  ('la_luna', 'la-luna', 'La Luna', 'major', 18, NULL, NULL, 'Paisajes internos, intuición y confusión nocturna.', 'Exploración de la psique, sueños y sensaciones que delinean caminos no racionales; señala incertidumbre, miedos ocultos y creatividad subconsciente. Invita a confiar en intuiciones, indagar símbolos personales y avanzar con cautela hasta que la claridad emerja desde la noche interior.', 'Confusión que confunde señales internas con fantasías; bloqueo para interpretar sueños o exageración del temor. Ofrece la oportunidad de establecer rutinas que clarifiquen percepciones, registrar sueños y buscar diálogo terapéutico o creativo para transformar la vaguedad en material comprensible.', '["intuición","sueños","misterio","subconsciente"]'::jsonb, '¿Qué intuición puedes observar hoy sin juzgarla?', 'open', 'tarot_card_la_luna', 180, 'published', false, 'La Luna — significado del Tarot | Creovision', 'Paisajes internos, intuición y confusión nocturna.', TIMESTAMPTZ '2026-08-27 00:00:00+00'),
  ('el_sol', 'el-sol', 'El Sol', 'major', 19, NULL, NULL, 'Claridad, vitalidad y logro expresado con alegría.', 'Brillo vital que ilumina proyectos y relaciones con honestidad y entusiasmo; favorece reconocimiento, energía constructiva y claridad de objetivos. Impulsa creatividad y buena disposición para celebrar avances concretos, nutriendo confianza y capacidad para compartir logros con autenticidad.', 'Euforia forzada o exceso de confianza que oculta aspectos pendientes; puede señalar necesidad de recuperar humildad práctica o atender detalles descuidados. Es un recordatorio para equilibrar celebración con responsabilidad y sostener energía sin diluir la atención en lo que falta consolidar.', '["claridad","vitalidad","éxito","alegría"]'::jsonb, '¿Qué logro merece ser celebrado hoy con honestidad?', 'favorable', 'tarot_card_el_sol', 190, 'published', false, 'El Sol — significado del Tarot | Creovision', 'Claridad, vitalidad y logro expresado con alegría.', TIMESTAMPTZ '2026-08-27 00:00:00+00'),
  ('el_juicio', 'el-juicio', 'El Juicio', 'major', 20, NULL, NULL, 'Llamado a evaluarte y renacer con propósito.', 'Convocatoria interna a revisar decisiones, reconocer lecciones y responder con integridad; favorece memoria constructiva que permite redefinir rumbo con mayor sentido. Marca un proceso de reconciliación con el pasado para actuar desde responsabilidad renovada y claridad de intenciones.', 'Duda sobre el llamado o miedo a asumir consecuencias; bloqueo para actuar pese a señales claras. Puede implicar postergación o autocrítica paralizante. Sugerencia de trabajar en criterios personales y dar pasos simbólicos que confirmen compromisos, más que esperar perfectas certezas.', '["evaluación","renacimiento","llamado","responsabilidad"]'::jsonb, '¿Qué lección pasada pide ser reconocida para avanzar?', 'open', 'tarot_card_el_juicio', 200, 'published', false, 'El Juicio — significado del Tarot | Creovision', 'Llamado a evaluarte y renacer con propósito.', TIMESTAMPTZ '2026-08-27 00:00:00+00'),
  ('el_mundo', 'el-mundo', 'El Mundo', 'major', 21, NULL, NULL, 'Cierre pleno y sensación de totalidad.', 'Culminación armoniosa de un ciclo que integra aprendizajes, relaciones y frutos; sensación de plenitud y conexión con el entorno. Invita a celebrar logros y reconocer participación propia en el proceso, abriendo paso a nuevas metas con confianza y visión ampliada.', 'Cierre incompleto o atracción por metas externas que postergan integración; sensación de logro aparente pero falta reconciliación interna. Señala la posibilidad de revisar lo que aún queda por integrar y ajustar expectativas antes de comenzar otra etapa con coherencia real.', '["culminación","integración","plenitud","cierre"]'::jsonb, '¿Qué aspecto de este logro necesita aún tu integración?', 'favorable', 'tarot_card_el_mundo', 210, 'published', false, 'El Mundo — significado del Tarot | Creovision', 'Cierre pleno y sensación de totalidad.', TIMESTAMPTZ '2026-08-27 00:00:00+00'),
  ('as_de_bastos', 'as-de-bastos', 'As de Bastos', 'minor', 1, 'wands', 'as', 'Semilla de energía creativa y comienzo impulsor.', 'Aparición de impulso creativo y ganas de iniciar proyectos; chispa que invita a explorar nuevas direcciones con confianza. Representa entusiasmo práctico y posibilidad de materializar ideas mediante acción decidida y atención al timing, recogiendo energía para sostener el arranque.', 'Idea o impulso sin madurar que necesita estructura; bloqueo por falta de planificación o exceso de entusiasmo disperso. Señala la oportunidad de definir pasos concretos, priorizar recursos y esperar el momento adecuado para que la semilla creativa germine con mayor solidez.', '["inicio","creatividad","impulso","oportunidad"]'::jsonb, '¿Cuál es el primer paso concreto para arrancar tu idea?', 'open', 'tarot_card_as_de_bastos', 220, 'published', false, 'As de Bastos — significado del Tarot | Creovision', 'Semilla de energía creativa y comienzo impulsor.', TIMESTAMPTZ '2026-08-27 00:00:00+00'),
  ('dos_de_bastos', 'dos-de-bastos', 'Dos de Bastos', 'minor', 2, 'wands', 'dos', 'Planificación desde visión personal hacia nuevas fronteras.', 'Periodo de planificación y visión a mediano plazo; evalúas opciones y delineas estrategia para expandir tus horizontes. Invita a tomar decisiones informadas, combinar ambición con recursos reales y anticipar obstáculos para que la iniciativa tenga una base sostenible.', 'Indecisión o temor a comprometerse que frena proyectos prometedores; bloqueo por falta de información o por cálculo excesivo. Sugiere recopilar datos, definir prioridades y probar rutas pequeñas que permitan convertir visión en prueba concreta antes de grandes apuestas.', '["planificación","decisión","visión","expansión"]'::jsonb, '¿Qué información te falta para decidir con más claridad?', 'caution', 'tarot_card_dos_de_bastos', 230, 'published', false, 'Dos de Bastos — significado del Tarot | Creovision', 'Planificación desde visión personal hacia nuevas fronteras.', TIMESTAMPTZ '2026-08-27 00:00:00+00'),
  ('tres_de_bastos', 'tres-de-bastos', 'Tres de Bastos', 'minor', 3, 'wands', 'tres', 'Expansión temprana y observación de resultados.', 'Resultados iniciales que confirman un rumbo y abren escenarios de expansión; observas consecuencias y ajustas rutas. Fomenta paciencia activa, delegación y búsqueda de alianzas para que el crecimiento se consolide más allá del esfuerzo individual.', 'Expectativas desajustadas o falta de seguimiento que ralentizan la expansión; bloqueo en convertir oportunidades en resultados. Indica la necesidad de revisar compromisos, mejorar comunicación con colaboradores y ajustar plazos para sostener el impulso con más realismo.', '["expansión","visión","alianzas","progreso"]'::jsonb, '¿Qué ajuste pequeño ayudaría a sostener este crecimiento?', 'favorable', 'tarot_card_tres_de_bastos', 240, 'published', false, 'Tres de Bastos — significado del Tarot | Creovision', 'Expansión temprana y observación de resultados.', TIMESTAMPTZ '2026-08-27 00:00:00+00'),
  ('cuatro_de_bastos', 'cuatro-de-bastos', 'Cuatro de Bastos', 'minor', 4, 'wands', 'cuatro', 'Celebración y base segura para comunidad.', 'Estabilidad visible y momento de celebración por hitos compartidos; refuerza sensación de pertenencia y seguridad en proyectos grupales. Invita a reconocer apoyos, consolidar acuerdos prácticos y disfrutar logros antes de plantear nuevas metas. Celebración sencilla y pausada que regenera energías.', 'Celebración prematura o responsabilidades ocultas que soslayan preocupaciones; bloqueo para consolidar la armonía a largo plazo. Puede señalar necesidad de revisar compromisos prácticos y mantener límites claros para que la convivencia o el trabajo en equipo perduren sin desgastes inesperados.', '["celebración","hogar","bases","comunidad"]'::jsonb, '¿Qué logro compartido merece reconocimiento y a quién debes agradecer?', 'favorable', 'tarot_card_cuatro_de_bastos', 250, 'published', false, 'Cuatro de Bastos — significado del Tarot | Creovision', 'Celebración y base segura para comunidad.', TIMESTAMPTZ '2026-08-27 00:00:00+00'),
  ('cinco_de_bastos', 'cinco-de-bastos', 'Cinco de Bastos', 'minor', 5, 'wands', 'cinco', 'Tensiones y competencia que empujan al cambio.', 'Conflicto creativo y competencia que sacude el terreno común; tensiones impulsan a probar límites, presentar ideas y negociar espacios. Energía caótica que exige adaptabilidad y habilidad para usar el choque como motor de crecimiento colectivo, no como derrota personal.', 'Bloqueo por evitación: las disputas se disuelven en silencio o se internalizan, frenando la innovación y dejando acuerdos implícitos. También puede indicar reapropiación de energía: se eligen batallas, se prioriza la colaboración estratégica y se redirige la tensión hacia objetivos concretos.', '["Competencia","Tensión creativa","Debate","Adaptación"]'::jsonb, '¿En qué situación actual deberías enfrentar la competencia en lugar de evitarla?', 'caution', 'tarot_card_cinco_de_bastos', 260, 'published', false, 'Cinco de Bastos — significado del Tarot | Creovision', 'Tensiones y competencia que empujan al cambio.', TIMESTAMPTZ '2026-08-27 00:00:00+00'),
  ('seis_de_bastos', 'seis-de-bastos', 'Seis de Bastos', 'minor', 6, 'wands', 'seis', 'Visibilidad y reconocimiento por esfuerzos realizados.', 'Reconocimiento público y avance visible tras esfuerzo sostenido; llegada de apoyo que confirma dirección. Momento para mostrar liderazgo con humildad, aceptar felicitaciones y usar la visibilidad para consolidar objetivos y fortalecer vínculos que permitan nuevos pasos.', 'Inseguridad ante el reconocimiento: el logro parece efímero, la atención no se traduce en apoyo real o se duda de la propia valía. Lectura alternativa: recalibrar expectativas, buscar respaldo tangible y reconocer avances sin depender sólo de la aprobación externa.', '["Reconocimiento","Victoria","Visibilidad","Liderazgo"]'::jsonb, '¿Cómo puedes aprovechar la visibilidad actual para fortalecer tus objetivos?', 'favorable', 'tarot_card_seis_de_bastos', 270, 'published', false, 'Seis de Bastos — significado del Tarot | Creovision', 'Visibilidad y reconocimiento por esfuerzos realizados.', TIMESTAMPTZ '2026-08-27 00:00:00+00'),
  ('siete_de_bastos', 'siete-de-bastos', 'Siete de Bastos', 'minor', 7, 'wands', 'siete', 'Defender lo construido frente a la presión externa.', 'Postura defensiva necesaria: mantener posición frente a desafíos y críticas, sosteniendo convicciones pese a la presión. Requiere energía, valentía y estrategia para proteger lo ganado, discernir prioridades y no dispersarse en múltiples frentes. Es un momento para elegir batallas con criterio y cuidar recursos.', 'Bloqueo por agotamiento o rigidez: la defensa se vuelve postureo o desgaste, impidiendo nuevas oportunidades. Alternativamente señala necesidad de replantear estrategia, soltar batallas menores y recuperar energía antes de sostener otra vez la posición con prudencia.', '["Defensa","Persistencia","Territorio","Selección"]'::jsonb, '¿Qué estás dispuesto a defender y qué puedes dejar ir?', 'caution', 'tarot_card_siete_de_bastos', 280, 'published', false, 'Siete de Bastos — significado del Tarot | Creovision', 'Defender lo construido frente a la presión externa.', TIMESTAMPTZ '2026-08-27 00:00:00+00'),
  ('ocho_de_bastos', 'ocho-de-bastos', 'Ocho de Bastos', 'minor', 8, 'wands', 'ocho', 'Ritmo rápido que impulsa acción y noticias.', 'Movimiento rápido y noticias que aceleran procesos; las circunstancias se alinean para avanzar con rapidez. Energía propulsora que empuja proyectos, comunicaciones y viajes; requiere claridad y preparación para aprovechar el impulso sin dispersarse. Es momento de decisiones ágiles y de confiar en la dinámica creada.', 'Bloqueo por retrasos o malentendidos: la velocidad se frena y la acción necesita revisión. Lectura alternativa: aprovechar la pausa para afinar detalles, reorganizar prioridades y preparar un impulso más sostenido cuando las condiciones vuelvan a ser favorables.', '["Rapidez","Comunicación","Movimiento","Impulso"]'::jsonb, '¿Qué decisión puedes tomar ahora para aprovechar el impulso?', 'favorable', 'tarot_card_ocho_de_bastos', 290, 'published', false, 'Ocho de Bastos — significado del Tarot | Creovision', 'Ritmo rápido que impulsa acción y noticias.', TIMESTAMPTZ '2026-08-27 00:00:00+00'),
  ('nueve_de_bastos', 'nueve-de-bastos', 'Nueve de Bastos', 'minor', 9, 'wands', 'nueve', 'Resiliencia y vigilancia tras experiencias difíciles.', 'Resistencia tras pruebas: guardas cicatrices y permaneces alerta, dispuesto a perseverar pese al cansancio. Indica fortaleza defensiva y preparación para un último esfuerzo; es prudente mantener límites y recuperar fuerzas antes de continuar con sentido estratégico.', 'Bloqueo por hipervigilancia: la protección excesiva impide confiar y recibir apoyo, generando agotamiento. Alternativamente sugiere oportunidad para sanar: reducir guardias selectivamente y permitir ayuda que facilite la recuperación y el cierre del ciclo con paciencia.', '["Resiliencia","Defensa","Perseverancia","Recuperación"]'::jsonb, '¿Qué necesitas recuperar antes de dar otro paso?', 'caution', 'tarot_card_nueve_de_bastos', 300, 'published', false, 'Nueve de Bastos — significado del Tarot | Creovision', 'Resiliencia y vigilancia tras experiencias difíciles.', TIMESTAMPTZ '2026-08-27 00:00:00+00'),
  ('diez_de_bastos', 'diez-de-bastos', 'Diez de Bastos', 'minor', 10, 'wands', 'diez', 'Carga excesiva que pide delegar y simplificar.', 'Carga excesiva que amenaza con agotar; asumes responsabilidades que pesan y limitan movimiento. Indica necesidad de delegar, simplificar o revisar compromisos para evitar quiebres; llevar todo solo ya no es sostenible. Busca apoyo y define prioridades claras.', 'Bloqueo por negación o reparto ineficaz: la carga se oculta o se reparte mal, perpetuando tensión. Alternativamente indica liberación inminente: soltar y confiar responsabilidades, creando espacio para mayor equilibrio y creatividad con intención y límites claros.', '["Carga","Delegar","Límites","Agotamiento"]'::jsonb, '¿Qué podrías delegar hoy para aliviar tu carga?', 'caution', 'tarot_card_diez_de_bastos', 310, 'published', false, 'Diez de Bastos — significado del Tarot | Creovision', 'Carga excesiva que pide delegar y simplificar.', TIMESTAMPTZ '2026-08-27 00:00:00+00'),
  ('paje_de_bastos', 'paje-de-bastos', 'Paje de Bastos', 'minor', NULL, 'wands', 'paje', 'Chispa de curiosidad e inicio creativo.', 'Mensaje o inspiración joven: surge curiosidad por un proyecto creativo o un llamado a explorar. Invita a experimentar con entusiasmo, a iniciar pasos pequeños y a comunicar ideas sin miedo al error; la chispa pide acción.', 'Bloqueo por inseguridad creativa o por impulsividad sin rumbo: la idea no se desarrolla o se abandona rápido. Alternativa: cultivar paciencia experimental, estructurar pequeños ensayos y convertir el impulso en aprendizaje sostenido con curiosidad y seguimiento.', '["Inspiración","Iniciativa","Curiosidad","Exploración"]'::jsonb, '¿Qué pequeño paso puedes dar hoy para probar esa idea?', 'open', 'tarot_card_paje_de_bastos', 320, 'published', false, 'Paje de Bastos — significado del Tarot | Creovision', 'Chispa de curiosidad e inicio creativo.', TIMESTAMPTZ '2026-08-27 00:00:00+00'),
  ('caballero_de_bastos', 'caballero-de-bastos', 'Caballero de Bastos', 'minor', NULL, 'wands', 'caballero', 'Impulso apasionado hacia la acción inmediata.', 'Acción decidida y energía aventurera: te mueves con pasión hacia metas y proyectos, asumiendo riesgos y acelerando procesos. Es momento de dinamismo, aunque conviene equilibrar impulso con claridad para evitar decisiones precipitadas y planificar tiempos.', 'Bloqueo por impaciencia o dispersión: el ímpetu lleva a saltos sin destino claro. Alternativamente indica necesidad de canalizar pasión hacia un plan concreto, acotar tiempos y cultivar disciplina para sostener impulso en el largo plazo.', '["Pasión","Impulso","Aventura","Rapidez"]'::jsonb, '¿Qué primer paso apasionado vas a tomar esta semana y cómo lo sostendrás?', 'open', 'tarot_card_caballero_de_bastos', 330, 'published', false, 'Caballero de Bastos — significado del Tarot | Creovision', 'Impulso apasionado hacia la acción inmediata.', TIMESTAMPTZ '2026-08-27 00:00:00+00'),
  ('reina_de_bastos', 'reina-de-bastos', 'Reina de Bastos', 'minor', NULL, 'wands', 'reina', 'Carisma y liderazgo creativo que inspira a otros.', 'Presencia cálida y segura: lideras con creatividad, magnetismo y generosidad, inspirando a otros. Combina intuición práctica con iniciativa; establece límites claros y promueve ambientes donde las ideas florecen con responsabilidad y alegría sin perder autenticidad.', 'Bloqueo por desbalance entre dar y cuidarse: la confianza se vuelve presión o sobreexposición. Alternativamente invita a reenfocar energía en autocuidado, delegar tareas y sostener el liderazgo desde límites saludables con ternura y coherencia personal.', '["Carisma","Liderazgo","Calor","Autenticidad"]'::jsonb, '¿Cómo puedes liderar con más autenticidad y cuidado propio?', 'favorable', 'tarot_card_reina_de_bastos', 340, 'published', false, 'Reina de Bastos — significado del Tarot | Creovision', 'Carisma y liderazgo creativo que inspira a otros.', TIMESTAMPTZ '2026-08-27 00:00:00+00'),
  ('rey_de_bastos', 'rey-de-bastos', 'Rey de Bastos', 'minor', NULL, 'wands', 'rey', 'Visión emprendedora con responsabilidad y acción.', 'Liderazgo visionario y determinación: emprendes con confianza estratégica, inspirando equipos y trazando rumbo a largo plazo. Combina audacia con responsabilidad, impulsando proyectos ambiciosos y manteniendo coherencia entre palabra y acción y cultivando alianzas sólidas estratégicas.', 'Bloqueo por exhibición autoritaria o prisa: el liderazgo pierde sintonía con el equipo. Alternativamente indica oportunidad para aprender a delegar, afinar comunicación y transformar ambición en mentoría efectiva con empatía y visión compartida de largo plazo.', '["Visión","Autoridad","Emprendimiento","Responsabilidad"]'::jsonb, '¿Cómo usarás tu influencia para sostener un proyecto a largo plazo?', 'favorable', 'tarot_card_rey_de_bastos', 350, 'published', false, 'Rey de Bastos — significado del Tarot | Creovision', 'Visión emprendedora con responsabilidad y acción.', TIMESTAMPTZ '2026-08-27 00:00:00+00'),
  ('as_de_copas', 'as-de-copas', 'As de Copas', 'minor', 1, 'cups', 'as', 'Apertura afectiva y fertilidad emocional.', 'Inicio emocional pleno: surge una apertura del corazón, nueva empatía o una ola creativa que invita a conectar. Representa disponibilidad afectiva y potencial para relaciones, perdón o inspiración artística si se permite sentir con honestidad.', 'Bloqueo emocional o integración incompleta: la apertura queda contenida o el sentimiento se desborda sin dirección. Alternativamente sugiere trabajar en límites afectivos y expresión auténtica para transformar la emoción en vínculo o creación consciente sostenida.', '["Emoción","Renovación","Apertura","Creatividad"]'::jsonb, '¿Qué sentir necesitas permitirte hoy para abrirte más?', 'favorable', 'tarot_card_as_de_copas', 360, 'published', false, 'As de Copas — significado del Tarot | Creovision', 'Apertura afectiva y fertilidad emocional.', TIMESTAMPTZ '2026-08-27 00:00:00+00'),
  ('dos_de_copas', 'dos-de-copas', 'Dos de Copas', 'minor', 2, 'cups', 'dos', 'Alianza y conexión basada en reciprocidad.', 'Encuentro equilibrado y conexión mutua: alianza emocional o colaboración basada en respeto y reciprocidad. Favorece acuerdos sinceros, reconciliaciones sanas y la construcción conjunta de proyectos afectivos o creativos con intención compartida que nutre crecimiento mutuo.', 'Bloqueo por desigualdad o dependencia emocional: la relación no fluye de manera equitativa. Alternativamente propone trabajar en comunicación clara, límites y redefinir acuerdos para restablecer armonía y respeto mutuo con honestidad y paciencia sostenida duradera.', '["Conexión","Reciprocidad","Alianza","Equilibrio"]'::jsonb, '¿Qué necesitas expresar para equilibrar esta relación?', 'favorable', 'tarot_card_dos_de_copas', 370, 'published', false, 'Dos de Copas — significado del Tarot | Creovision', 'Alianza y conexión basada en reciprocidad.', TIMESTAMPTZ '2026-08-27 00:00:00+00'),
  ('tres_de_copas', 'tres-de-copas', 'Tres de Copas', 'minor', 3, 'cups', 'tres', 'Celebración colectiva que fortalece lazos.', 'Celebración compartida y apoyo comunitario: momentos de alegría que fortalecen lazos, colaboración y creatividad colectiva. Favorece encuentros que sostienen el ánimo, reconocen logros y permiten compartir recursos emocionales con quienes aportan confianza; celebrar con moderación y gratitud.', 'Bloqueo por aislamiento o reuniones superficiales: la celebración se diluye o no aparece. Alternativa: cultivar encuentros genuinos, seleccionar compañía que nutra y transformar la celebración en apoyo concreto y renovación de vínculos con intención constante.', '["Celebración","Comunidad","Apoyo","Alegría"]'::jsonb, '¿A quién te gustaría invitar para celebrar un logro?', 'favorable', 'tarot_card_tres_de_copas', 380, 'published', false, 'Tres de Copas — significado del Tarot | Creovision', 'Celebración colectiva que fortalece lazos.', TIMESTAMPTZ '2026-08-27 00:00:00+00'),
  ('cuatro_de_copas', 'cuatro-de-copas', 'Cuatro de Copas', 'minor', 4, 'cups', 'cuatro', 'Necesidad de retiro emocional para reevaluar ofertas y deseos.', 'Momento de retiro emocional donde la insatisfacción nubla la percepción; tenderás a cerrar el corazón ante ofertas que parecen superficiales, invitando a reevaluar necesidades afectivas y a buscar claridad interna antes de responder, con paciencia.', 'Señal de ruptura del estancamiento emocional; al girar aparece la posibilidad de aceptar nuevas ofertas, reabrir el corazón y tomar decisiones conscientes, aunque el cambio requiera esfuerzo para salir de la indiferencia y reparar la participación emocional.', '["introspección","desapego","oportunidades ignoradas"]'::jsonb, '¿Qué oportunidad emocional estoy ignorando por apatía?', 'caution', 'tarot_card_cuatro_de_copas', 390, 'published', false, 'Cuatro de Copas — significado del Tarot | Creovision', 'Necesidad de retiro emocional para reevaluar ofertas y deseos.', TIMESTAMPTZ '2026-08-27 00:00:00+00'),
  ('cinco_de_copas', 'cinco-de-copas', 'Cinco de Copas', 'minor', 5, 'cups', 'cinco', 'Proceso de duelo que obliga a mirar lo perdido y reconocer apoyos remanentes.', 'Dolor y duelo por pérdidas reales o esperanzas rotas; la atención se fija en lo perdido, dificultando ver apoyos y posibilidades que permanecen, lo que pide permiso para sentir y empezar a recomponer el corazón con tiempo y compañía.', 'Lectura de recuperación o bloqueo: indica que la aceptación comienza a abrir perspectiva; también puede señalar resistencia a dejar ir, demorando la reconstrucción emocional hasta que se permita integrar la experiencia y reconocer lo que aún sostiene.', '["duelo","pérdida","apoyo restante"]'::jsonb, '¿Qué necesito aceptar para empezar a sanar?', 'caution', 'tarot_card_cinco_de_copas', 400, 'published', false, 'Cinco de Copas — significado del Tarot | Creovision', 'Proceso de duelo que obliga a mirar lo perdido y reconocer apoyos remanentes.', TIMESTAMPTZ '2026-08-27 00:00:00+00'),
  ('seis_de_copas', 'seis-de-copas', 'Seis de Copas', 'minor', 6, 'cups', 'seis', 'Reconexión con la inocencia y gestos de ternura que evocan el pasado.', 'Recuerdos cálidos y gestos sencillos que reconectan con inocencia y generosidad; favores del pasado o reconciliaciones pueden traer consuelo, inspirando actos de bondad y la posibilidad de integrar lecciones infantiles en relaciones presentes con intención y equilibrio.', 'Bloqueo por idealizar el pasado o resistencia a cambiar; puede señalar que la nostalgia impide ver necesidades actuales, invitando a reinterpretar recuerdos sin perder la ternura, y a ofrecer cariño desde madurez más que desde hábito.', '["nostalgia","reconciliación","inocencia","generosidad"]'::jsonb, '¿Qué aspecto del pasado merece ser honrado sin quedarse estancado?', 'open', 'tarot_card_seis_de_copas', 410, 'published', false, 'Seis de Copas — significado del Tarot | Creovision', 'Reconexión con la inocencia y gestos de ternura que evocan el pasado.', TIMESTAMPTZ '2026-08-27 00:00:00+00'),
  ('siete_de_copas', 'siete-de-copas', 'Siete de Copas', 'minor', 7, 'cups', 'siete', 'Multitud de opciones emocionales que requieren discernimiento para no perderse en la fantasía.', 'Lluvia de opciones emocionales y fantasías que estimulan la imaginación pero confunden la voluntad; pide discernimiento para distinguir sueños realizables de quimeras, priorizando valores y compromisos antes de elegir y evaluar consecuencias prácticas con honestidad.', 'Lectura de bloqueo o claridad emergente: señala que la confusión empieza a ceder y que es posible enfocar la energía; también puede indicar paralización por miedo a elegir, pidiendo pasos pequeños para probar opciones antes de comprometerse.', '["opciones","fantasía vs realidad","discernimiento"]'::jsonb, '¿Cuál opción es coherente con mis valores actuales?', 'caution', 'tarot_card_siete_de_copas', 420, 'published', false, 'Siete de Copas — significado del Tarot | Creovision', 'Multitud de opciones emocionales que requieren discernimiento para no perderse en la fantasía.', TIMESTAMPTZ '2026-08-27 00:00:00+00'),
  ('ocho_de_copas', 'ocho-de-copas', 'Ocho de Copas', 'minor', 8, 'cups', 'ocho', 'Salir de una situación insatisfactoria para buscar sentido y autenticidad interior.', 'Decisión consciente de abandonar una situación emocional insatisfactoria para buscar sentido más profundo; implica dejar atrás cómodas familiaridades y emprender un camino interior que prioriza crecimiento y autenticidad sobre seguridad conocida a largo plazo personal.', 'Bloqueo o retorno: puede indicar dificultad para soltar, un intento prematuro de volver atrás o la necesidad de revisar motivos internos; alternativamente anuncia el inicio del viaje interior cuando se acepta el vacío como oportunidad.', '["abandono","búsqueda interior","renuncia necesaria"]'::jsonb, '¿Qué estoy dispuesto a dejar para buscar más autenticidad?', 'open', 'tarot_card_ocho_de_copas', 430, 'published', false, 'Ocho de Copas — significado del Tarot | Creovision', 'Salir de una situación insatisfactoria para buscar sentido y autenticidad interior.', TIMESTAMPTZ '2026-08-27 00:00:00+00'),
  ('nueve_de_copas', 'nueve-de-copas', 'Nueve de Copas', 'minor', 9, 'cups', 'nueve', 'Plenitud emocional momentánea que celebra deseos cumplidos y bienestar personal.', 'Satisfacción personal y disfrute de logros afectivos; momento de gratitud por deseos cumplidos y reconexión con el propio bienestar, celebrando placeres simples sin necesidad de justificar lo alcanzado en compañía o en soledad, con humildad.', 'Alternativa que invita a revisar qué se desea realmente: puede señalar que la satisfacción externa no llena el vacío interno, o que los deseos evolucionan, pidiendo honestidad para ajustar metas afectivas a un sentido más profundo.', '["satisfacción","deseo cumplido","gratitud"]'::jsonb, '¿Este logro alimenta verdaderamente mi bienestar interior?', 'favorable', 'tarot_card_nueve_de_copas', 440, 'published', false, 'Nueve de Copas — significado del Tarot | Creovision', 'Plenitud emocional momentánea que celebra deseos cumplidos y bienestar personal.', TIMESTAMPTZ '2026-08-27 00:00:00+00'),
  ('diez_de_copas', 'diez-de-copas', 'Diez de Copas', 'minor', 10, 'cups', 'diez', 'Armonía relacional profunda que ofrece sentido de pertenencia y estabilidad afectiva.', 'Armonía emocional profunda y sentido de pertenencia; relaciones cercanas ofrecen apoyo y alegría compartida, señalando un período de estabilidad afectiva donde se consolidan compromisos y se celebran vínculos con plena conexión, duradera, serena y recíproca siempre.', 'Lectura alternativa: puede señalar que la imagen ideal de felicidad requiere ajuste o que existen tensiones ocultas; invita a redefinir qué constituye hogar y a trabajar la comunicación para recuperar la sensación de plenitud sincera.', '["armonía","hogar","plenitud","conexión"]'::jsonb, '¿Qué necesito cultivar hoy para que mi vínculo se sienta más auténtico?', 'favorable', 'tarot_card_diez_de_copas', 450, 'published', false, 'Diez de Copas — significado del Tarot | Creovision', 'Armonía relacional profunda que ofrece sentido de pertenencia y estabilidad afectiva.', TIMESTAMPTZ '2026-08-27 00:00:00+00'),
  ('paje_de_copas', 'paje-de-copas', 'Paje de Copas', 'minor', NULL, 'cups', 'paje', 'Aparición de inspiración emocional o mensaje afectivo que despierta curiosidad.', 'Aparición de un mensaje emocional o de una inspiración creativa que despierta ternura y curiosidad; invita a recibir señales del corazón, explorar nuevas sensibilidades y expresarlas con honestidad juguetona y apertura y respeto por el propio ritmo.', 'Lectura de bloqueo o inmadurez emocional: sugiere que la creatividad se detiene por inseguridad o impulsividad; invita a escuchar antes de responder, practicar contención emocional y permitir que la expresión madure sin prisas, con tiempo.', '["mensaje emocional","creatividad","apertura"]'::jsonb, '¿Cómo puedo expresar una idea emocional sin apresurarme?', 'open', 'tarot_card_paje_de_copas', 460, 'published', false, 'Paje de Copas — significado del Tarot | Creovision', 'Aparición de inspiración emocional o mensaje afectivo que despierta curiosidad.', TIMESTAMPTZ '2026-08-27 00:00:00+00'),
  ('caballero_de_copas', 'caballero-de-copas', 'Caballero de Copas', 'minor', NULL, 'cups', 'caballero', 'Movimiento afectivo que trae propuestas y gestos cargados de sensibilidad.', 'Figura en movimiento que ofrece cortesía, propuestas románticas o proyectos creativos impulsados por la sensibilidad; anima a actuar desde el corazón con elegancia y a llevar gestos comprometidos hacia quienes importan de forma sencilla y auténtica.', 'Bloqueo o idealismo: puede señalar promesas vagas, indecisión afectiva o gestos que necesitan coherencia; invita a pedir claridad sobre intenciones y a equilibrar emoción con responsabilidad antes de aceptar una oferta que implique compromiso real.', '["romanticismo","oferta emocional","cortesía"]'::jsonb, '¿Esta propuesta está alineada con mis valores emocionales?', 'caution', 'tarot_card_caballero_de_copas', 470, 'published', false, 'Caballero de Copas — significado del Tarot | Creovision', 'Movimiento afectivo que trae propuestas y gestos cargados de sensibilidad.', TIMESTAMPTZ '2026-08-27 00:00:00+00'),
  ('reina_de_copas', 'reina-de-copas', 'Reina de Copas', 'minor', NULL, 'cups', 'reina', 'Sabiduría empática que contiene y nutre desde la intuición y la estabilidad.', 'Madurez emocional y empatía profunda; capacidad de escuchar, contener y comprender sin juicio, ofreciendo apoyo nutritivo que integra intuición con sabiduría práctica y fomenta seguridad afectiva en el entorno de forma estable, serena y constante.', 'Bloqueo o protección necesaria: puede indicar exceso de entrega que agota o retraimiento para protegerse; sugiere restablecer límites saludables y practicar autocuidado de forma consciente y gradual para recuperar equilibrio entre dar y recibir plenamente.', '["empatía","intuitiva","contención","sabiduría emocional"]'::jsonb, '¿Cómo voy a proteger mi energía emocional mientras acompaño a otros?', 'favorable', 'tarot_card_reina_de_copas', 480, 'published', false, 'Reina de Copas — significado del Tarot | Creovision', 'Sabiduría empática que contiene y nutre desde la intuición y la estabilidad.', TIMESTAMPTZ '2026-08-27 00:00:00+00'),
  ('rey_de_copas', 'rey-de-copas', 'Rey de Copas', 'minor', NULL, 'cups', 'rey', 'Autoridad afectiva que dirige con templanza y equilibrio emocional.', 'Liderazgo sereno que integra inteligencia emocional y empatía; administra sentimientos con ecuanimidad, apoya con prudencia y guía afectiva, representando equilibrio entre compasión y responsabilidad en decisiones vinculadas al corazón, de manera firme y justa siempre.', 'Bloqueo o contención: puede señalar emociones administradas en exceso que generan distancia, o bien dificultad para mostrar ternura; invita a integrar sensibilidad auténtica con límites claros para evitar frialdad o evasión emocional y recuperar conexión genuina.', '["equilibrio emocional","liderazgo","templanza"]'::jsonb, '¿Cómo ejerzo mi autoridad sin perder sensibilidad?', 'favorable', 'tarot_card_rey_de_copas', 490, 'published', false, 'Rey de Copas — significado del Tarot | Creovision', 'Autoridad afectiva que dirige con templanza y equilibrio emocional.', TIMESTAMPTZ '2026-08-27 00:00:00+00'),
  ('as_de_espadas', 'as-de-espadas', 'As de Espadas', 'minor', 1, 'swords', 'as', 'Claridad mental que permite cortes decisivos y comunicación precisa.', 'Claridad mental y apertura a una idea decisiva; momento de corte con dudas, pensamiento nítido y capacidad para comunicar verdades esenciales que permiten avance estratégico y resolución de conflictos intelectuales con integridad y enfoque sostenido.', 'Bloqueo o lectura alternativa: señala confusión, prejuicios mentales o comunicados imprecisos; invita a pausar, examinar supuestos y buscar fuentes claras, responsable y reflexivamente, para decisiones acertadas.', '["claridad","verdad","decisión","intelecto"]'::jsonb, '¿Qué idea debo expresar ahora con honestidad?', 'favorable', 'tarot_card_as_de_espadas', 500, 'published', false, 'As de Espadas — significado del Tarot | Creovision', 'Claridad mental que permite cortes decisivos y comunicación precisa.', TIMESTAMPTZ '2026-08-27 00:00:00+00'),
  ('dos_de_espadas', 'dos-de-espadas', 'Dos de Espadas', 'minor', 2, 'swords', 'dos', 'Dilema que exige balance entre la razón y el sentimiento para desbloquear la decisión.', 'Dilema que demanda balance entre razón y sentimiento; postura defensiva o bloqueo mental impide decidir, pidiendo honestidad interna, abrir canales de diálogo y sopesar información para liberar la inmovilidad con pasos pequeños y realistas apacibles.', 'Lectura de desbloqueo o evitación: puede indicar que la indecisión se disuelve y que se vislumbran alternativas, o bien que se continúa evitando información crucial; invita a bajar defensas y obtener hechos claros y verificables.', '["decisión","bloqueo","equilibrio","compromiso"]'::jsonb, '¿Qué información falta para tomar una decisión honesta ahora?', 'caution', 'tarot_card_dos_de_espadas', 510, 'published', false, 'Dos de Espadas — significado del Tarot | Creovision', 'Dilema que exige balance entre la razón y el sentimiento para desbloquear la decisión.', TIMESTAMPTZ '2026-08-27 00:00:00+00'),
  ('tres_de_espadas', 'tres-de-espadas', 'Tres de Espadas', 'minor', 3, 'swords', 'tres', 'Herida emocional que obliga a enfrentar verdades incómodas.', 'Dolor emocional que revela verdades necesarias; el choque de la separación o la traición abre una herida que obliga a reconocer lo que no funciona y a clarificar sentimientos antes de sanar y a revisar límites personales.', 'Bloqueo interno que evita enfrentar el dolor; puede indicar negación, supresión o una reparación lenta que aún no se percibe; la protección emocional impide procesar la pérdida y retrasa la comprensión necesaria y solicita tiempo y apoyo.', '["dolor","separación","claridad","herida"]'::jsonb, '¿Qué verdad dolorosa evité reconocer y cómo cambiaría mi actitud si la aceptara?', 'caution', 'tarot_card_tres_de_espadas', 520, 'published', false, 'Tres de Espadas — significado del Tarot | Creovision', 'Herida emocional que obliga a enfrentar verdades incómodas.', TIMESTAMPTZ '2026-08-27 00:00:00+00'),
  ('cuatro_de_espadas', 'cuatro-de-espadas', 'Cuatro de Espadas', 'minor', 4, 'swords', 'cuatro', 'Pausa y retiro necesarios para recuperar fuerzas y ordenar la mente.', 'Necesidad de descanso y retiro; apartarse del conflicto para recuperar energías, reorganizar ideas y permitir que la mente se calme antes de decidir; la pausa es deliberada y favorece la recuperación mental y la planificación desde mayor serenidad.', 'Resistencia a detenerse o aislamiento prolongado que impide avanzar; la retirada puede convertirse en evasión, o la incapacidad de descansar sabotea la recuperación, necesitando establecer límites y buscar apoyo para no estancarse y permitir procesos.', '["descanso","retiro","recuperación","pausa"]'::jsonb, '¿Qué actividad o distancia necesito para recargarme antes de tomar decisiones?', 'favorable', 'tarot_card_cuatro_de_espadas', 530, 'published', false, 'Cuatro de Espadas — significado del Tarot | Creovision', 'Pausa y retiro necesarios para recuperar fuerzas y ordenar la mente.', TIMESTAMPTZ '2026-08-27 00:00:00+00'),
  ('cinco_de_espadas', 'cinco-de-espadas', 'Cinco de Espadas', 'minor', 5, 'swords', 'cinco', 'Conflicto que deja una victoria vacía y obliga a valorar el costo humano.', 'Conflicto agudo y consecuencias de una victoria a costa de otros; enfrentamientos dejan resentimiento y pérdida de confianza, provocando que gane la razón pero no la armonía; invita a evaluar si la disputa es imprescindible y aprender de la experiencia.', 'Evitar la confrontación o aceptar la derrota para preservar relaciones; también puede señalar baja autoestima que impide defender límites, sugiriendo revisar estrategias y comunicar necesidades sin agresión y buscar soluciones colaborativas y apoyo externo cuando haga falta.', '["conflicto","victoria costosa","tensión","evaluación"]'::jsonb, '¿Qué gano y qué pierdo con esta confrontación?', 'caution', 'tarot_card_cinco_de_espadas', 540, 'published', false, 'Cinco de Espadas — significado del Tarot | Creovision', 'Conflicto que deja una victoria vacía y obliga a valorar el costo humano.', TIMESTAMPTZ '2026-08-27 00:00:00+00'),
  ('seis_de_espadas', 'seis-de-espadas', 'Seis de Espadas', 'minor', 6, 'swords', 'seis', 'Tránsito hacia un estado más tranquilo que implica aceptar y reorganizar prioridades.', 'Tránsito hacia un lugar más tranquilo, dejar atrás turbulencias; cambio mental que requiere aceptación y ayuda externa; la travesía simboliza alivio gradual y reordenamiento de prioridades hacia mayor claridad mientras se procesan experiencias recientes y se planifica el siguiente paso.', 'Estancamiento en el cambio, miedo a partir o viajar sin rumbo claro; transición bloqueada por dudas o dependencia, pide identificar recursos prácticos y pasos pequeños para recuperar movimiento y volver a establecer dirección con apoyo planificado.', '["transición","viaje","alivio","movimiento"]'::jsonb, '¿Qué debo dejar atrás para avanzar con mayor calma?', 'favorable', 'tarot_card_seis_de_espadas', 550, 'published', false, 'Seis de Espadas — significado del Tarot | Creovision', 'Tránsito hacia un estado más tranquilo que implica aceptar y reorganizar prioridades.', TIMESTAMPTZ '2026-08-27 00:00:00+00'),
  ('siete_de_espadas', 'siete-de-espadas', 'Siete de Espadas', 'minor', 7, 'swords', 'siete', 'Ingenio y discreción para sortear problemas, con necesidad de evaluar consecuencias.', 'Estrategia discreta, actuar con sigilo o tomar iniciativas no convencionales; plantea usar astucia para sortear obstáculos, pero también invita a considerar consecuencias éticas y la necesidad de transparencia y evaluar si el beneficio compensa el aislamiento que puede generar.', 'Deseo de escapar de responsabilidades o miedo a afrontar conflictos, bloqueo para tomar decisiones estratégicas; puede impulsar reconsiderar métodos y buscar soluciones colaborativas en vez de maniobras solitarias y fomentar confianza ahora.', '["estrategia","sigilo","astucia","evasión"]'::jsonb, '¿Estoy eligiendo el camino más inteligente o simplemente evitando confrontaciones?', 'caution', 'tarot_card_siete_de_espadas', 560, 'published', false, 'Siete de Espadas — significado del Tarot | Creovision', 'Ingenio y discreción para sortear problemas, con necesidad de evaluar consecuencias.', TIMESTAMPTZ '2026-08-27 00:00:00+00'),
  ('ocho_de_espadas', 'ocho-de-espadas', 'Ocho de Espadas', 'minor', 8, 'swords', 'ocho', 'Ataduras mentales que limitan opciones y piden revisar creencias.', 'Sensación de estar atrapado por pensamientos, limitaciones percibidas que paralizan; las ataduras suelen ser mentales y piden identificar creencias que cortan opciones para empezar a recuperar agencia mediante pequeños pasos y buscar apoyo para ampliar perspectivas.', 'Salida gradual de la sensación de prisión mental; reconocimiento de alternativas y valentía para probar cambios, aunque persisten inseguridades; la inversión muestra apertura para romper patrones limitantes si hay voluntad y sostén comunitario con pasos concretos.', '["limitación","miedo","parálisis","creencias"]'::jsonb, '¿Qué pensamiento debo cuestionar para recuperar opciones reales?', 'caution', 'tarot_card_ocho_de_espadas', 570, 'published', false, 'Ocho de Espadas — significado del Tarot | Creovision', 'Ataduras mentales que limitan opciones y piden revisar creencias.', TIMESTAMPTZ '2026-08-27 00:00:00+00'),
  ('nueve_de_espadas', 'nueve-de-espadas', 'Nueve de Espadas', 'minor', 9, 'swords', 'nueve', 'Angustia que se intensifica en la noche y pide herramientas para calmar la mente.', 'Angustia nocturna y preocupaciones que se exageran en la mente; pensamientos repetitivos alimentan ansiedad y causan dificultad para descansar, pidiendo técnicas concretas para gestionar la rumiación y reconectar con recursos prácticos de apoyo diarios sostenibles.', 'Superación gradual de la angustia o bloqueo que impide pedir ayuda; la inversión indica que las preocupaciones empiezan a clarificarse, permitiendo ensayar hábitos que mejoran el sueño y la perspectiva y la resiliencia emocional.', '["angustia","insomnio","rumiación","preocupación"]'::jsonb, '¿Qué práctica diaria podría reducir mi ansiedad y mejorar mi descanso?', 'caution', 'tarot_card_nueve_de_espadas', 580, 'published', false, 'Nueve de Espadas — significado del Tarot | Creovision', 'Angustia que se intensifica en la noche y pide herramientas para calmar la mente.', TIMESTAMPTZ '2026-08-27 00:00:00+00'),
  ('diez_de_espadas', 'diez-de-espadas', 'Diez de Espadas', 'minor', 10, 'swords', 'diez', 'Cierre drástico que marca un límite y abre la posibilidad de recomponer lo esencial.', 'Final doloroso o colapso de una situación; sensación de límite absoluto que obliga aceptar lo irrecuperable y empezar a imaginar cómo recomponer desde lo esencial; anuncia punto de inflexión visible y la posibilidad de rehacer con nuevos aprendizajes y apoyos concretos.', 'Resistencia al cierre o negación del daño que impide el reinicio; puede señalar recuperación silenciosa que aún no se muestra o la necesidad de aceptar ayuda para recomponer la vida paso a paso y tomar decisiones prácticas.', '["final","colapso","reinicio","punto límite"]'::jsonb, '¿Qué es irrevocable ahora y cómo puedo empezar a reconstruir desde lo esencial?', 'caution', 'tarot_card_diez_de_espadas', 590, 'published', false, 'Diez de Espadas — significado del Tarot | Creovision', 'Cierre drástico que marca un límite y abre la posibilidad de recomponer lo esencial.', TIMESTAMPTZ '2026-08-27 00:00:00+00'),
  ('paje_de_espadas', 'paje-de-espadas', 'Paje de Espadas', 'minor', NULL, 'swords', 'paje', 'Mensajero de curiosidad e investigación que fomenta observación y verificación.', 'Mensajero de ideas, curiosidad y vigilancia intelectual; trae preguntas, señales o necesidad de investigar; favorece la observación ágil y la honestidad mental para clarificar situaciones emergentes y practicar comunicación precisa manteniendo apertura y paciencia para validar datos.', 'Impulsividad mental, rumores o interrupciones informativas que confunden; bloqueo para concentrarse o miedo a preguntar, sugiere ordenar fuentes y moderar reacciones antes de actuar y practicar verificación y paciencia comunicativa para recuperar claridad gradual.', '["curiosidad","mensaje","investigación","vigilancia"]'::jsonb, '¿Qué información necesito confirmar antes de formarme una opinión?', 'open', 'tarot_card_paje_de_espadas', 600, 'published', false, 'Paje de Espadas — significado del Tarot | Creovision', 'Mensajero de curiosidad e investigación que fomenta observación y verificación.', TIMESTAMPTZ '2026-08-27 00:00:00+00'),
  ('caballero_de_espadas', 'caballero-de-espadas', 'Caballero de Espadas', 'minor', NULL, 'swords', 'caballero', 'Impulso decidido para actuar con rapidez, cuidando la precipitación.', 'Movimiento rápido e impulso intelectual; energía decidida para enfrentar problemas y defender ideas con urgencia; requiere cuidar la precipitación para no perder detalle ni generar conflictos innecesarios y planificar coordinación con otros cuando sea necesario.', 'Impulsividad desenfrenada o bloqueo por dudas repentinas que frenan acción; la inversión sugiere recalibrar ritmo, revisar motivaciones y considerar consecuencias antes de lanzarse y coordinar con apoyo estratégico y establecer prioridades claras y realistas siempre.', '["impulso","rapidez","decisión","precaución"]'::jsonb, '¿Estoy actuando por convicción o por impulso del momento?', 'caution', 'tarot_card_caballero_de_espadas', 610, 'published', false, 'Caballero de Espadas — significado del Tarot | Creovision', 'Impulso decidido para actuar con rapidez, cuidando la precipitación.', TIMESTAMPTZ '2026-08-27 00:00:00+00'),
  ('reina_de_espadas', 'reina-de-espadas', 'Reina de Espadas', 'minor', NULL, 'swords', 'reina', 'Intelecto claro que establece límites y comunica con honestidad.', 'Intelecto claro y comunicación directa; capacidad para cortar lo superfluo con honestidad y compasión contenida; representa límites bien trazados y juicio desapasionado que protege autonomía y verdad y fomenta responsabilidad y pensamiento crítico en lo diario.', 'Distancia emocional excesiva o rigidez que impide empatizar; bloqueo para expresar ternura o emergen juicios autoexigentes, pidiendo equilibrio entre verdad y cuidado humano y ejercicios prácticos para flexibilizar la comunicación afectiva y la escucha activa ayudan a restaurar balance.', '["claridad","discernimiento","límites","honestidad"]'::jsonb, '¿Cómo puedo decir la verdad sin apagar la calidez en mi comunicación?', 'open', 'tarot_card_reina_de_espadas', 620, 'published', false, 'Reina de Espadas — significado del Tarot | Creovision', 'Intelecto claro que establece límites y comunica con honestidad.', TIMESTAMPTZ '2026-08-27 00:00:00+00'),
  ('rey_de_espadas', 'rey-de-espadas', 'Rey de Espadas', 'minor', NULL, 'swords', 'rey', 'Liderazgo intelectual que combina juicio justo y responsabilidad.', 'Razonamiento maduro y liderazgo intelectual; capacidad para tomar decisiones justas basadas en análisis claro y principios; combina autoridad con responsabilidad y ofrece perspectiva estratégica en asuntos complejos y orientación práctica cuando se requiere firmeza y ética.', 'Rigidez intelectual o abuso de autoridad que paraliza el diálogo; bloqueo para integrar otras voces, o muestra la necesidad de revisar decisiones con humildad y datos actualizados y procesos consultivos para recuperar legitimidad de manera efectiva.', '["liderazgo","razón","justicia","autoridad"]'::jsonb, '¿Qué principios debo priorizar al tomar esta decisión difícil?', 'favorable', 'tarot_card_rey_de_espadas', 630, 'published', false, 'Rey de Espadas — significado del Tarot | Creovision', 'Liderazgo intelectual que combina juicio justo y responsabilidad.', TIMESTAMPTZ '2026-08-27 00:00:00+00'),
  ('as_de_oros', 'as-de-oros', 'As de Oros', 'minor', 1, 'pentacles', 'as', 'Oportunidad material incipiente que pide disciplina y gestión cuidadosa.', 'Semilla de abundancia práctica y oportunidad tangible; inicio de proyectos con apoyo material, estabilidad creciente y posibilidad de progreso sostenible si se aplican disciplina y planificación realista y cuidado en la gestión de recursos diaria.', 'Oportunidad latente bloqueada por falta de preparación o miedo a comprometer recursos; inversión o proyecto retrasa su inicio, pidiendo análisis práctico y pasos escalonados para activarlo y colaboración estratégica y revisión de prioridades financieras claras.', '["oportunidad","abundancia","inicio","estabilidad"]'::jsonb, '¿Qué primer paso práctico puedo dar para convertir esta semilla en realidad?', 'favorable', 'tarot_card_as_de_oros', 640, 'published', false, 'As de Oros — significado del Tarot | Creovision', 'Oportunidad material incipiente que pide disciplina y gestión cuidadosa.', TIMESTAMPTZ '2026-08-27 00:00:00+00'),
  ('dos_de_oros', 'dos-de-oros', 'Dos de Oros', 'minor', 2, 'pentacles', 'dos', 'Equilibrio fluido entre obligaciones y recursos en movimiento.', 'Equilibrio dinámico entre recursos y responsabilidades; requiere adaptarse a cambios financieros o logísticos sin perder movilidad. Prioriza la flexibilidad, la gestión del tiempo y la atención a prioridades urgentes para mantener estabilidad mientras aparecen nuevas oportunidades o demandas.', 'Bloqueo en la capacidad de coordinar múltiples frentes: la atención dispersa o compromisos excesivos generan agotamiento. Es señal para simplificar prioridades, delegar o renegociar plazos, y recuperar una base estable antes de intentar sostener más cargas o proyectos simultáneos.', '["equilibrio","adaptabilidad","gestión recursos"]'::jsonb, '¿Qué dos prioridades puedo equilibrar ahora para evitar sobrecarga?', 'open', 'tarot_card_dos_de_oros', 650, 'published', false, 'Dos de Oros — significado del Tarot | Creovision', 'Equilibrio fluido entre obligaciones y recursos en movimiento.', TIMESTAMPTZ '2026-08-27 00:00:00+00'),
  ('tres_de_oros', 'tres-de-oros', 'Tres de Oros', 'minor', 3, 'pentacles', 'tres', 'Colaboración práctica que reconoce la habilidad y el trabajo bien hecho.', 'Colaboración aplicada y reconocimiento por habilidad; el trabajo conjunto con estándares claros produce progreso tangible. Valora la técnica, la comunicación y el aprendizaje práctico; es momento de consolidar proyectos con apoyo mutuo y validar esfuerzos mediante resultados concretos y calidad compartida.', 'Lectura alternativa que señala desajuste entre expectativas y capacidades: falta coordinación, o la calidad no muestra el potencial esperado. En lugar de culpar, ofrece oportunidad para afinar técnicas, aclarar roles y reconstruir relaciones profesionales antes de buscar reconocimiento externo.', '["colaboración","maestría","reconocimiento"]'::jsonb, '¿Qué habilidad debería pulir para aportar mejor al equipo?', 'favorable', 'tarot_card_tres_de_oros', 660, 'published', false, 'Tres de Oros — significado del Tarot | Creovision', 'Colaboración práctica que reconoce la habilidad y el trabajo bien hecho.', TIMESTAMPTZ '2026-08-27 00:00:00+00'),
  ('cuatro_de_oros', 'cuatro-de-oros', 'Cuatro de Oros', 'minor', 4, 'pentacles', 'cuatro', 'Consolidación y preservación de recursos para sostener seguridad.', 'Protección y acumulación para asegurar una base material; prioriza la preservación de recursos, la disciplina financiera y el control sobre lo conocido. Es momento de consolidar seguridad, aunque ello implique limitar gastos y evitar riesgos innecesarios mientras se cimenta estabilidad.', 'Lectura alternativa que sugiere liberar el apego excesivo: retener por miedo puede detener el flujo de oportunidades. Considera redistribuir recursos, invertir en crecimiento o compartir responsabilidades; soltar control calculado puede abrir espacio para nuevas formas de seguridad más flexibles.', '["seguridad","ahorro","control"]'::jsonb, '¿Qué estoy guardando por seguridad y qué podría compartir o invertir?', 'caution', 'tarot_card_cuatro_de_oros', 670, 'published', false, 'Cuatro de Oros — significado del Tarot | Creovision', 'Consolidación y preservación de recursos para sostener seguridad.', TIMESTAMPTZ '2026-08-27 00:00:00+00'),
  ('cinco_de_oros', 'cinco-de-oros', 'Cinco de Oros', 'minor', 5, 'pentacles', 'cinco', 'Momento de escasez que exige buscar apoyo y ajustar prioridades.', 'Indica dificultades materiales o sensación de exclusión; puede manifestarse como escasez, gasto inesperado o apoyo insuficiente. No es sentencia: señala la necesidad de buscar recursos alternativos, pedir ayuda práctica, ajustar presupuestos y priorizar autocuidado para transitar la carencia con mayor resiliencia.', 'Lectura alternativa que anuncia la posibilidad de alivio: recepción de apoyo, redes que se activan o recursos recuperados. También puede señalar la necesidad de aceptar asistencia práctica y reorganizar prioridades para que la mejora sea sostenible en el tiempo.', '["escasez","apoyo","resiliencia"]'::jsonb, '¿A quién puedo acudir ahora por ayuda práctica?', 'caution', 'tarot_card_cinco_de_oros', 680, 'published', false, 'Cinco de Oros — significado del Tarot | Creovision', 'Momento de escasez que exige buscar apoyo y ajustar prioridades.', TIMESTAMPTZ '2026-08-27 00:00:00+00'),
  ('seis_de_oros', 'seis-de-oros', 'Seis de Oros', 'minor', 6, 'pentacles', 'seis', 'Intercambio equilibrado donde dar y recibir se sostienen mutuamente.', 'Flujo solidario entre dar y recibir; implica compartir recursos con justicia, apoyar a otros o recibir ayuda sin culpa. Destaca la equidad, la transparencia y la reciprocidad; administra recursos con generosidad responsable y evita desequilibrios que comprometan la propia estabilidad.', 'Lectura alternativa que advierte sobre desequilibrios en el intercambio: ayuda condicionada, dependencia o límites poco claros. Señala revisar acuerdos, establecer límites claros y valorar la sostenibilidad de dar para que la generosidad no se convierta en carga ni impida recibir apoyo legítimo.', '["generosidad","reciprocidad","justicia"]'::jsonb, '¿Daré sin poner en riesgo mi estabilidad?', 'favorable', 'tarot_card_seis_de_oros', 690, 'published', false, 'Seis de Oros — significado del Tarot | Creovision', 'Intercambio equilibrado donde dar y recibir se sostienen mutuamente.', TIMESTAMPTZ '2026-08-27 00:00:00+00'),
  ('siete_de_oros', 'siete-de-oros', 'Siete de Oros', 'minor', 7, 'pentacles', 'siete', 'Evaluación paciente del progreso y decisión sobre continuidad o ajuste.', 'Periodo de evaluación de esfuerzos y frutos sembrados; invita a medir progreso con paciencia, revisar estrategias y decidir si continuar o ajustar el rumbo. Valora la constancia y la visión a largo plazo antes de consumir o redirigir los recursos acumulados.', 'Lectura alternativa que indica frustración por resultados lentos o inversión que tarda en madurar. Puede pedir reevaluar métodos, buscar asesoría o aceptar que algunos proyectos requieren cambio de enfoque; no es fracaso, es momento de aprender y ajustar tiempos.', '["paciencia","evaluación","visión larga"]'::jsonb, '¿Qué indicador me dirá si sigo o cambio de estrategia?', 'open', 'tarot_card_siete_de_oros', 700, 'published', false, 'Siete de Oros — significado del Tarot | Creovision', 'Evaluación paciente del progreso y decisión sobre continuidad o ajuste.', TIMESTAMPTZ '2026-08-27 00:00:00+00'),
  ('ocho_de_oros', 'ocho-de-oros', 'Ocho de Oros', 'minor', 8, 'pentacles', 'ocho', 'Dedicación a la práctica y perfeccionamiento mediante trabajo constante.', 'Enfoque en la práctica, perfeccionamiento y trabajo consistente; la dedicación a la técnica produce maestría y reconocimiento a futuro. Es época de aprender con disciplina, repetir procesos, pulir detalles y construir reputación mediante la calidad del trabajo cotidiano.', 'Lectura alternativa que muestra bloqueo por rutina: trabajo repetitivo que agota o falta de sentido en la práctica. Indica la urgencia de variar métodos, buscar inspiración, delegar tareas monótonas o integrar pausas para preservar motivación y creatividad.', '["maestría","disciplina","práctica"]'::jsonb, '¿Qué habilidad debo practicar hoy para mejorar en lo que hago?', 'favorable', 'tarot_card_ocho_de_oros', 710, 'published', false, 'Ocho de Oros — significado del Tarot | Creovision', 'Dedicación a la práctica y perfeccionamiento mediante trabajo constante.', TIMESTAMPTZ '2026-08-27 00:00:00+00'),
  ('nueve_de_oros', 'nueve-de-oros', 'Nueve de Oros', 'minor', 9, 'pentacles', 'nueve', 'Autonomía y disfrute de los frutos del esfuerzo con refinamiento.', 'Autonomía material y disfrute del fruto del esfuerzo; seguridad lograda mediante disciplina permite comodidad y placer refinado. Invita a valorar independencia, cultivar recursos personales y celebrar logros con moderación, manteniendo una base sólida para el bienestar sostenido.', 'Lectura alternativa que indica que el confort podría ser frágil o aislante: la seguridad material existe, pero requiere mantenimiento y conexión. Invita a revisar inversiones, reforzar redes de apoyo y equilibrar el disfrute personal con responsabilidad a largo plazo.', '["autonomía","abundancia","disfrute"]'::jsonb, '¿Cómo sostengo mi confort sin aislarme ni arriesgarlo?', 'favorable', 'tarot_card_nueve_de_oros', 720, 'published', false, 'Nueve de Oros — significado del Tarot | Creovision', 'Autonomía y disfrute de los frutos del esfuerzo con refinamiento.', TIMESTAMPTZ '2026-08-27 00:00:00+00'),
  ('diez_de_oros', 'diez-de-oros', 'Diez de Oros', 'minor', 10, 'pentacles', 'diez', 'Patrimonio y estabilidad familiar que aseguran continuidad y tranquilidad.', 'Fundación duradera de bienestar material y legado familiar; señala seguridad construida a lo largo del tiempo y armonía en asuntos prácticos. Invita a consolidar patrimonio, formalizar acuerdos y transmitir conocimientos o recursos para asegurar continuidad y tranquilidad intergeneracional.', 'Lectura alternativa que muestra estructuras patrimoniales rígidas o expectativas desalineadas; puede requerir actualización de planes, diálogo familiar y transparencia legal para evitar malentendidos. También sugiere evaluar si la preservación material sirve a los valores que se desean transmitir.', '["legado","seguridad","patrimonio"]'::jsonb, '¿Qué quiero dejar como legado práctico y por qué?', 'favorable', 'tarot_card_diez_de_oros', 730, 'published', false, 'Diez de Oros — significado del Tarot | Creovision', 'Patrimonio y estabilidad familiar que aseguran continuidad y tranquilidad.', TIMESTAMPTZ '2026-08-27 00:00:00+00'),
  ('paje_de_oros', 'paje-de-oros', 'Paje de Oros', 'minor', NULL, 'pentacles', 'paje', 'Mensaje práctico que inicia aprendizaje y proyectos concretos.', 'Mensaje práctico y nuevo comienzo en lo material o educativo; energía joven orientada al aprendizaje, planificación y proyectos concretos. Invita a estudiar, preparar propuestas y experimentar con metodología responsable; es un inicio prometedor que se construye con curiosidad y disciplina aplicada.', 'Lectura alternativa que advierte sobre iniciativas insuficientemente preparadas o información incompleta: la idea existe pero requiere más formación, pruebas o estructura práctica. Recomienda volver a los fundamentos, solicitar orientación y consolidar detalles antes de avanzar.', '["oportunidad","estudio","inicio"]'::jsonb, '¿Qué paso práctico puedo dar hoy para avanzar en mi proyecto?', 'open', 'tarot_card_paje_de_oros', 740, 'published', false, 'Paje de Oros — significado del Tarot | Creovision', 'Mensaje práctico que inicia aprendizaje y proyectos concretos.', TIMESTAMPTZ '2026-08-27 00:00:00+00'),
  ('caballero_de_oros', 'caballero-de-oros', 'Caballero de Oros', 'minor', NULL, 'pentacles', 'caballero', 'Ritmo constante, responsabilidad y logro mediante perseverancia.', 'Avance constante y responsabilidad aplicada; representa compromiso laboral, enfoque metódico y logro por perseverancia. Favorece planes sólidos, cumplimiento de tareas y cuidado por los detalles; su ritmo puede ser lento, pero produce resultados confiables si se mantiene la disciplina.', 'Lectura alternativa que señala rigidez o exceso de cautela: el método funciona, pero puede bloquear oportunidades que requieren adaptación. Invita a evaluar si es necesario flexibilizar plazos, delegar o incorporar nuevas técnicas para acelerar progreso sin sacrificar calidad.', '["constancia","responsabilidad","metódico"]'::jsonb, '¿Dónde puedo ser más flexible sin perder control del proyecto?', 'caution', 'tarot_card_caballero_de_oros', 750, 'published', false, 'Caballero de Oros — significado del Tarot | Creovision', 'Ritmo constante, responsabilidad y logro mediante perseverancia.', TIMESTAMPTZ '2026-08-27 00:00:00+00'),
  ('reina_de_oros', 'reina-de-oros', 'Reina de Oros', 'minor', NULL, 'pentacles', 'reina', 'Cuidado práctico que nutre prosperidad y bienestar cotidiano.', 'Voz de cuidado material y pragmatismo afectuoso; combina sensibilidad con capacidad para administrar recursos y crear un hogar o ambiente próspero. Apoya iniciativas prácticos, salud financiera y bienestar cotidiano mediante organización, hospitalidad y decisiones terrenales bien fundadas.', 'Lectura alternativa que sugiere descuidar el autocuidado o delegar en exceso: la capacidad de sostener a otros existe, pero requiere atención personal y límites. Recomienda revisar finanzas domésticas, priorizar descanso y delegar responsabilidades para preservar la eficacia nutritiva.', '["cuidado","prosperidad","practicidad"]'::jsonb, '¿Qué necesito para cuidar mejor mi bienestar material y emocional?', 'favorable', 'tarot_card_reina_de_oros', 760, 'published', false, 'Reina de Oros — significado del Tarot | Creovision', 'Cuidado práctico que nutre prosperidad y bienestar cotidiano.', TIMESTAMPTZ '2026-08-27 00:00:00+00'),
  ('rey_de_oros', 'rey-de-oros', 'Rey de Oros', 'minor', NULL, 'pentacles', 'rey', 'Maestría en lo material con liderazgo y gestión responsable.', 'Combinación de éxito material y sabiduría práctica; símbolo de liderazgo responsable en negocios y recursos. Emana seguridad, visión estratégica y habilidad para multiplicar lo tangible con ética profesional. Fomenta inversiones sólidas, gestión inteligente y cuidado del patrimonio con confianza serena.', 'Lectura alternativa que apunta a exceso de conservadurismo o prioridades materialistas que aíslan: quizá convenga revisar estrategias de crecimiento, compartir responsabilidades de gestión o actualizar modelos para alinear riqueza con impacto social y personal. Es momento de combinar prudencia con apertura a nuevos usos del capital.', '["liderazgo","abundancia","gestión patrimonial"]'::jsonb, '¿Cómo puedo usar mis recursos para crear valor duradero?', 'favorable', 'tarot_card_rey_de_oros', 770, 'published', false, 'Rey de Oros — significado del Tarot | Creovision', 'Maestría en lo material con liderazgo y gestión responsable.', TIMESTAMPTZ '2026-08-27 00:00:00+00')
